import java.io.*;
import java.util.*;

public class Main {
    static int seed = 123456789;

    static int rnd() {
        seed ^= seed << 13;
        seed ^= seed >>> 17;
        seed ^= seed << 5;
        return seed;
    }

    static class Node {
        long key;
        int prio, cnt, size;
        Node left, right;

        Node(long key) {
            this.key = key;
            this.prio = rnd();
            this.cnt = 1;
            this.size = 1;
        }
    }

    static int size(Node n) {
        return n == null ? 0 : n.size;
    }

    static void update(Node n) {
        n.size = n.cnt + size(n.left) + size(n.right);
    }

    static Node rotateRight(Node y) {
        Node x = y.left;
        y.left = x.right;
        x.right = y;
        update(y);
        update(x);
        return x;
    }

    static Node rotateLeft(Node x) {
        Node y = x.right;
        x.right = y.left;
        y.left = x;
        update(x);
        update(y);
        return y;
    }

    static Node insert(Node t, long key) {
        if (t == null) return new Node(key);

        if (key == t.key) {
            t.cnt++;
            t.size++;
            return t;
        } else if (key < t.key) {
            t.left = insert(t.left, key);
            if (t.left.prio < t.prio) t = rotateRight(t);
        } else {
            t.right = insert(t.right, key);
            if (t.right.prio < t.prio) t = rotateLeft(t);
        }

        update(t);
        return t;
    }

    static int query(Node t, long key) {
        int ans = 0;
        while (t != null) {
            if (key < t.key) {
                t = t.left;
            } else {
                ans += size(t.left) + t.cnt;
                t = t.right;
            }
        }
        return ans;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());

        StringBuilder sb = new StringBuilder();
        Node root = null;
        long prevPenalty = 0;

        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            long x = Long.parseLong(st.nextToken());
            long y = Long.parseLong(st.nextToken());

            long xr = x + prevPenalty;
            long yr = y + prevPenalty;
            long dist2 = xr * xr + yr * yr;

            int penalty = query(root, dist2);
            sb.append(penalty).append('\n');

            root = insert(root, dist2);
            prevPenalty = penalty;
        }

        System.out.print(sb);
    }
}
